	/** 
	 * jumpstart the process by instantiating2 Territory
	 */
	protected void jumpStart() throws Throwable {
		LOGGER.info( "\n======== create instances to get the ball rolling  ======== ");

		territoryId = TerritoryService.getTerritoryInstance()
		.createTerritory( generateNewCommand() )
		.get();

		// ---------------------------------------------
		// set up query subscriptions after the 1st create
		// ---------------------------------------------
		testingStep = "create";
		setUpQuerySubscriptions();

		TerritoryService.getTerritoryInstance()
				.createTerritory( generateNewCommand() )
				.get();

	}

	/** 
	 * Set up query subscriptions
	 */
	protected void setUpQuerySubscriptions() throws Throwable {
		LOGGER.info( "\n======== Setting Up Query Subscriptions ======== ");
			
		try {            
			subscriber.territorySubscribe().updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetAll update received for Territory : " + successValue.getTerritoryId());
							  if (successValue.getTerritoryId().equals(territoryId)) {
								  if (testingStep.equals("create")) {
									  testingStep = "update";
									  update();
								  } else if (testingStep.equals("delete")) {
									  testingStep = "complete";
									  state( getAll().size() == sizeOfTerritoryList - 1 , "value not deleted from list");
									  LOGGER.info("**********************************************************");
									  LOGGER.info("Territory test completed successfully...");
									  LOGGER.info("**********************************************************\n");
								  }
							  }
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on territory consumed")
					);
			subscriber.territorySubscribe( territoryId ).updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetOne update received for Territory : " + successValue.getTerritoryId() + " in step " + testingStep);
							  testingStep = "delete";
							  sizeOfTerritoryList = getAll().size();
							  delete();
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on territory for territoryId consumed")

					);
			

			}
			catch (Exception e) {
				LOGGER.warning( e.getMessage() );
				throw e;
			}
		}
		
		/** 
	 * read a Territory. 
	 */
	protected Territory read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created Territory" );

		Territory entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read Territory with primary key" );
		msg.append( territoryId );
		
		TerritoryFetchOneSummary fetchOneSummary = new TerritoryFetchOneSummary( territoryId );

		try {
			entity = TerritoryService.getTerritoryInstance().getTerritory( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found Territory " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a Territory.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a Territory." );

		StringBuilder msg = new StringBuilder( "Failed to update a Territory : " );        
		Territory entity = read();
		UpdateTerritoryCommand command = generateUpdateCommand();
		command.setTerritoryId(entity.getTerritoryId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created Territory." );

			// for use later on...
			territoryId = entity.getTerritoryId();

			TerritoryService proxy = TerritoryService.getTerritoryInstance();  

			proxy.updateTerritory( command ).get();

			LOGGER.info( "-- Successfully saved Territory - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + territoryId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a Territory.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created Territory." );

		Territory entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read Territory with id " + territoryId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read Territory with id " + territoryId );

			throw e;
		}

		try{
			TerritoryService.getTerritoryInstance().delete( new DeleteTerritoryCommand( entity.getTerritoryId() ) ).get();
			LOGGER.info( "-- Successfully deleted Territory with id " + territoryId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete Territory with id " + territoryId );

			throw e;
		}
	}

	/**
	 * get all Territorys.
	 */
	protected List<Territory> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of Territorys:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all Territory : " );        
		List<Territory> collection  = new ArrayList<>();

		try {
			// call the static get method on the TerritoryService
			collection = TerritoryService.getTerritoryInstance().getAllTerritory();
			assertNotNull( collection, "An Empty collection of Territory was incorrectly returned.");
			
			// Now print out the values
			Territory entity = null;            
			Iterator<Territory> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getTerritoryId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

